    vals = []
    mask = (1 << n) - 1
    for i in range(8):
        vals.append(x & mask)
        x = x >> n
    vals.reverse()
    return vals

def get_chrs(val_list, n):
    x = val_list[0]
    chrs = []
    for i in range(1, len(val_list)):
        x <<= n
        x += val_list[i]
    for i in range(n):
        chrs.append(chr(x % 256))
        x //= 256
    chrs.reverse()
    return "".join(chrs)

def decrypt_block(cipher_block, n, known_bytes=None):
    c_vals = get_vals(cipher_block, n)
    result = None
    # key candidates for flag{ (ASCII: 102/108/97/103/123)
    prefix = b'flag{'
    # Only try keys of 5 bytes; derive k_vals to match
    for first_k in range(1 << n):
        for second_k in range(1 << n):
            for third_k in range(1 << n):
                for fourth_k in range(1 << n):
                    for fifth_k in range(1 << n):
                        k_candidate = [first_k, second_k, third_k, fourth_k, fifth_k]
                        # Try to reconstruct m (plaintext), for first 5 bytes
                        m_candidate = []
                        valid = True
                        for i in range(5):
                            m_val = (c_vals[i] - k_candidate[i]) % (1 << n)
                            # try as candidate for ASCII
                            if m_val != prefix[i]:
                                valid = False
                                break
                        if valid:
                            result = k_candidate
                            return result
    return None

def main():
    # Read ciphertext
    ct_hex = Path("/home/ctfplayer/ctf_files/ciphertext").read_text().replace("\n", "")
    ct_bytes = bytes.fromhex(ct_hex)

    out = []
    prefix_found = False
    for n in range(2, 8):
        ct_blocks = get_nums(ct_bytes, n)
        for block in ct_blocks[:2]: # only first block(s)
            k_candidate = decrypt_block(block, n)
            if k_candidate:
