import itertools
import string

# Utilities to parse the challenge's python and ciphertext
def to_num(s):
    x = 0
    for i in range(len(s)):
        x += ord(s[-1-i]) * pow(256, i)
    return x

def get_nums(s, n):
    sections = [s[i:i+n] for i in range(0, len(s), n)]
    sections[-1] = sections[-1] + ("\x00" * (n - len(sections[-1])))
    return [to_num(x) for x in sections]

def get_vals(x, n):
    vals = []
    mask = (1 << n) - 1
    for i in range(8):
        vals.append(x & mask)
        x = x >> n
    vals.reverse()
    return vals

def get_chrs(val_list, n):
    x = val_list[0]
    chrs = []
    for i in range(1, len(val_list)):
        x <<= n
        x += val_list[i]
    for i in range(n):
        chrs.append(chr(x % 256))
        x //= 256
    chrs.reverse()
    return "".join(chrs)

def encr_vals(m_chr, k_chr, n):
    return (m_chr + k_chr) & ((1 << n) - 1)

def load_ciphertext(filename):
    with open(filename, 'r') as f:
        s = f.read().strip().replace("\n", "")
        return bytes.fromhex(s)

# Try to recover the n-bit key, assuming plaintext pattern (WORD) appears at each offset
def candidate_keys_for_pattern(ciphervals, flagpattern, n, ascii_range=(32,127)):
    keys = []
    for offset in range(len(ciphervals) - len(flagpattern) + 1):
        segment = ciphervals[offset:offset+len(flagpattern)]
        candidate = []
        plausible = True
        for i, c in enumerate(segment):
            k = (c - ord(flagpattern[i])) % (1<<n)
            # Optionally, only accept lowercase/printable plausible keys
            if not (ascii_range[0] <= k < ascii_range[1]):
                plausible = False
                break
            candidate.append(k)
        if plausible:
            keys.append( (offset, candidate) )
    return keys

# Merge/union overlapping key segments
# (if two candidate segments overlap and agree in their overlap, merge; else skip)
def merge_segments(keys1, keys2):
    merged = []
    for off1, seg1 in keys1:
        for off2, seg2 in keys2:
            start = min(off1, off2)
            end = max(off1+len(seg1), off2+len(seg2))
            overlap = min(off1+len(seg1), off2+len(seg2)) - max(off1,off2)
            if overlap <= 0:
                continue
            # check overlap
            agree = True
